//! Shopping aisles for names the catalog doesn't know, from Open Food Facts
//! ("cheerios", "cheez it", "rice cakes"): the category taxonomy's English
//! names and synonyms, and US product names and brands whose products agree
//! on an aisle. Generated by `make catalog-import-off`.
//!
//! Contains data from Open Food Facts (https://world.openfoodfacts.org),
//! available under the Open Database License
//! (https://opendatacommons.org/licenses/odbl/1.0/).

use std::collections::{BTreeMap, HashMap};
use std::sync::LazyLock;

use serde::Deserialize;

use crate::ingredient_categorizer::CATEGORIES;

const OPEN_FOOD_FACTS_JSON: &str = include_str!("data/open_food_facts.json");

/// The generated file also carries its attribution and sources, for readers.
#[derive(Deserialize)]
struct OpenFoodFactsFile {
    names: BTreeMap<String, String>,
}

static NAMES: LazyLock<HashMap<String, &'static str>> = LazyLock::new(|| {
    let file: OpenFoodFactsFile =
        serde_json::from_str(OPEN_FOOD_FACTS_JSON).expect("invalid catalog open_food_facts.json");
    file.names
        .into_iter()
        .map(|(name, aisle)| {
            assert_eq!(
                name,
                key(&name),
                "open_food_facts.json name {name:?} is not a key"
            );
            let aisle = CATEGORIES
                .into_iter()
                .find(|&c| c == aisle)
                .unwrap_or_else(|| panic!("{name:?} has unknown aisle {aisle:?}"));
            (name, aisle)
        })
        .collect()
});

/// Lowercase, drop apostrophes, and turn other punctuation into spaces, as
/// `scripts/import-open-food-facts.py` keys names ("Cheez-It" is "cheez it").
fn key(name: &str) -> String {
    name.to_lowercase()
        .chars()
        .filter(|&c| c != '\'' && c != '\u{2019}')
        .map(|c| if c.is_alphanumeric() { c } else { ' ' })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

/// The aisle Open Food Facts gives `name`, as written or as a plural or
/// singular ("cheez its" is "cheez it").
pub fn category(name: &str) -> Option<&'static str> {
    let name = key(name);
    std::iter::once(name.clone())
        .chain(super::resolve::plural_variants(&name))
        .find_map(|variant| NAMES.get(&variant).copied())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keys_match_the_importer() {
        assert_eq!(key("Cheez-It"), "cheez it");
        assert_eq!(key("S\u{2019}mores"), "smores");
        assert_eq!(key("  Ben & Jerry's  "), "ben jerrys");
    }

    #[test]
    fn plurals_and_singulars_match() {
        assert_eq!(category("cheez its"), Some("Snacks"));
        assert_eq!(category("pretzels"), Some("Snacks"));
    }

    #[test]
    fn broad_roots_take_what_their_products_mostly_are() {
        // Products tagged only "fats" are butter and spreads, and only
        // "cooking helpers" baking goods.
        assert_eq!(category("european style butter"), Some("Dairy & Eggs"));
        assert_eq!(category("vegetable fats"), Some("Oils & Vinegars"));
        assert_eq!(category("muffin mix"), Some("Baking"));
    }
}
